    /**
     * Performs an INSERT on the database, given a ComMigmasivo or Criteria object.
     *
     * @param      mixed $values Criteria or ComMigmasivo object containing data that is used to create the INSERT statement.
     * @param      PropelPDO $con the PropelPDO connection to use
     * @return mixed           The new primary key.
     * @throws PropelException Any exceptions caught during processing will be
     *		 rethrown wrapped into a PropelException.
     */
    public static function doInsert($values, PropelPDO $con = null)
    {
        if ($con === null) {
            $con = Propel::getConnection(ComMigmasivoPeer::DATABASE_NAME, Propel::CONNECTION_WRITE);
        }

        if ($values instanceof Criteria) {
            $criteria = clone $values; // rename for clarity
        } else {
            $criteria = $values->buildCriteria(); // build Criteria from ComMigmasivo object
        }

        if ($criteria->containsKey(ComMigmasivoPeer::COMMIGMASIVO_ID) && $criteria->keyContainsValue(ComMigmasivoPeer::COMMIGMASIVO_ID) ) {
            throw new PropelException('Cannot insert a value for auto-increment primary key ('.ComMigmasivoPeer::COMMIGMASIVO_ID.')');
        }

        // remove pkey col since this table uses auto-increment and passing a null value for it is not valid
        $criteria->remove(ComMigmasivoPeer::COMMIGMASIVO_ID);


        // Set the correct dbName
        $criteria->setDbName(ComMigmasivoPeer::DATABASE_NAME);

        try {
            // use transaction because $criteria could contain info
            // for more than one table (I guess, conceivably)
            $con->beginTransaction();
            $pk = BasePeer::doInsert($criteria, $con);
            $con->commit();
        } catch (Exception $e) {
            $con->rollBack();
            throw $e;
        }

        return $pk;
    }

    /**
     * Performs an UPDATE on the database, given a ComMigmasivo or Criteria object.
     *
     * @param      mixed $values Criteria or ComMigmasivo object containing data that is used to create the UPDATE statement.
     * @param      PropelPDO $con The connection to use (specify PropelPDO connection object to exert more control over transactions).
     * @return int             The number of affected rows (if supported by underlying database driver).
     * @throws PropelException Any exceptions caught during processing will be
     *		 rethrown wrapped into a PropelException.
     */
    public static function doUpdate($values, PropelPDO $con = null)
    {
        if ($con === null) {
            $con = Propel::getConnection(ComMigmasivoPeer::DATABASE_NAME, Propel::CONNECTION_WRITE);
        }

        $selectCriteria = new Criteria(ComMigmasivoPeer::DATABASE_NAME);

        if ($values instanceof Criteria) {
            $criteria = clone $values; // rename for clarity

            $comparison = $criteria->getComparison(ComMigmasivoPeer::COMMIGMASIVO_ID);
            $value = $criteria->remove(ComMigmasivoPeer::COMMIGMASIVO_ID);
            if ($value) {
                $selectCriteria->add(ComMigmasivoPeer::COMMIGMASIVO_ID, $value, $comparison);
            } else {
                $selectCriteria->setPrimaryTableName(ComMigmasivoPeer::TABLE_NAME);
            }

            $comparison = $criteria->getComparison(ComMigmasivoPeer::COMLOTE_ID);
            $value = $criteria->remove(ComMigmasivoPeer::COMLOTE_ID);
            if ($value) {
                $selectCriteria->add(ComMigmasivoPeer::COMLOTE_ID, $value, $comparison);
            } else {
                $selectCriteria->setPrimaryTableName(ComMigmasivoPeer::TABLE_NAME);
            }

        } else { // $values is ComMigmasivo object
            $criteria = $values->buildCriteria(); // gets full criteria
            $selectCriteria = $values->buildPkeyCriteria(); // gets criteria w/ primary key(s)
        }

        // set the correct dbName
        $criteria->setDbName(ComMigmasivoPeer::DATABASE_NAME);

        return BasePeer::doUpdate($selectCriteria, $criteria, $con);
    }

    /**
     * Deletes all rows from the COM_MIGMASIVO table.
     *
     * @param      PropelPDO $con the connection to use
     * @return int             The number of affected rows (if supported by underlying database driver).
     * @throws PropelException
     */
    public static function doDeleteAll(PropelPDO $con = null)
    {
        if ($con === null) {
            $con = Propel::getConnection(ComMigmasivoPeer::DATABASE_NAME, Propel::CONNECTION_WRITE);
        }
        $affectedRows = 0; // initialize var to track total num of affected rows
        try {
            // use transaction because $criteria could contain info
            // for more than one table or we could emulating ON DELETE CASCADE, etc.
            $con->beginTransaction();
            $affectedRows += BasePeer::doDeleteAll(ComMigmasivoPeer::TABLE_NAME, $con, ComMigmasivoPeer::DATABASE_NAME);
            // Because this db requires some delete cascade/set null emulation, we have to
            // clear the cached instance *after* the emulation has happened (since
            // instances get re-added by the select statement contained therein).
            ComMigmasivoPeer::clearInstancePool();
            ComMigmasivoPeer::clearRelatedInstancePool();
            $con->commit();

            return $affectedRows;
        } catch (Exception $e) {
            $con->rollBack();
            throw $e;
        }
    }

    /**
     * Performs a DELETE on the database, given a ComMigmasivo or Criteria object OR a primary key value.
     *
     * @param      mixed $values Criteria or ComMigmasivo object or primary key or array of primary keys
     *              which is used to create the DELETE statement
     * @param      PropelPDO $con the connection to use
     * @return int The number of affected rows (if supported by underlying database driver).  This includes CASCADE-related rows
     *				if supported by native driver or if emulated using Propel.
     * @throws PropelException Any exceptions caught during processing will be
     *		 rethrown wrapped into a PropelException.
     */
     public static function doDelete($values, PropelPDO $con = null)
     {
        if ($con === null) {
            $con = Propel::getConnection(ComMigmasivoPeer::DATABASE_NAME, Propel::CONNECTION_WRITE);
        }

        if ($values instanceof Criteria) {
            // invalidate the cache for all objects of this type, since we have no
            // way of knowing (without running a query) what objects should be invalidated
            // from the cache based on this Criteria.
            ComMigmasivoPeer::clearInstancePool();
            // rename for clarity
            $criteria = clone $values;
        } elseif ($values instanceof ComMigmasivo) { // it's a model object
            // invalidate the cache for this single object
            ComMigmasivoPeer::removeInstanceFromPool($values);
            // create criteria based on pk values
            $criteria = $values->buildPkeyCriteria();
        } else { // it's a primary key, or an array of pks
            $criteria = new Criteria(ComMigmasivoPeer::DATABASE_NAME);
            // primary key is composite; we therefore, expect
            // the primary key passed to be an array of pkey values
            if (count($values) == count($values, COUNT_RECURSIVE)) {
                // array is not multi-dimensional
                $values = array($values);
            }
            foreach ($values as $value) {
                $criterion = $criteria->getNewCriterion(ComMigmasivoPeer::COMMIGMASIVO_ID, $value[0]);
                $criterion->addAnd($criteria->getNewCriterion(ComMigmasivoPeer::COMLOTE_ID, $value[1]));
                $criteria->addOr($criterion);
                // we can invalidate the cache for this single PK
                ComMigmasivoPeer::removeInstanceFromPool($value);
            }
        }

        // Set the correct dbName
        $criteria->setDbName(ComMigmasivoPeer::DATABASE_NAME);

        $affectedRows = 0; // initialize var to track total num of affected rows

        try {
            // use transaction because $criteria could contain info
            // for more than one table or we could emulating ON DELETE CASCADE, etc.
            $con->beginTransaction();
            
            $affectedRows += BasePeer::doDelete($criteria, $con);
            ComMigmasivoPeer::clearRelatedInstancePool();
            $con->commit();

            return $affectedRows;
        } catch (Exception $e) {
            $con->rollBack();
            throw $e;
        }
    }

    /**
     * Validates all modified columns of given ComMigmasivo object.
     * If parameter $columns is either a single column name or an array of column names
     * than only those columns are validated.
     *
     * NOTICE: This does not apply to primary or foreign keys for now.
     *
     * @param ComMigmasivo $obj The object to validate.
     * @param      mixed $cols Column name or array of column names.
     *
     * @return mixed TRUE if all columns are valid or the error message of the first invalid column.
     */
    public static function doValidate($obj, $cols = null)
    {
        $columns = array();

        if ($cols) {
            $dbMap = Propel::getDatabaseMap(ComMigmasivoPeer::DATABASE_NAME);
            $tableMap = $dbMap->getTable(ComMigmasivoPeer::TABLE_NAME);

            if (! is_array($cols)) {
                $cols = array($cols);
            }

            foreach ($cols as $colName) {
                if ($tableMap->hasColumn($colName)) {
                    $get = 'get' . $tableMap->getColumn($colName)->getPhpName();
                    $columns[$colName] = $obj->$get();
                }
            }
        } else {

        }

        return BasePeer::doValidate(ComMigmasivoPeer::DATABASE_NAME, ComMigmasivoPeer::TABLE_NAME, $columns);
    }

    /**
     * Retrieve object using using composite pkey values.
     * @param   int $commigmasivo_id
     * @param   string $comlote_id
     * @param      PropelPDO $con
     * @return ComMigmasivo
     */
    public static function retrieveByPK($commigmasivo_id, $comlote_id, PropelPDO $con = null) {
        $_instancePoolKey = serialize(array((string) $commigmasivo_id, (string) $comlote_id));
         if (null !== ($obj = ComMigmasivoPeer::getInstanceFromPool($_instancePoolKey))) {
             return $obj;
        }

        if ($con === null) {
            $con = Propel::getConnection(ComMigmasivoPeer::DATABASE_NAME, Propel::CONNECTION_READ);
        }
        $criteria = new Criteria(ComMigmasivoPeer::DATABASE_NAME);
        $criteria->add(ComMigmasivoPeer::COMMIGMASIVO_ID, $commigmasivo_id);
        $criteria->add(ComMigmasivoPeer::COMLOTE_ID, $comlote_id);
        $v = ComMigmasivoPeer::doSelect($criteria, $con);

        return !empty($v) ? $v[0] : null;
    }
